    //         context: InputContext_<Path, Options> & {
    //             returnHeaders: true;
    //             returnStatus: true;
    //         },
    //     ): Promise<{ headers: Headers; status: number; response: Awaited<R> }>;
    //     (
    //         context: InputContext_<Path, Options> & {
    //             returnHeaders: true;
    //             returnStatus: false;
    //         },
    //     ): Promise<{ headers: Headers; response: Awaited<R> }>;
    //     (
    //         context: InputContext_<Path, Options> & {
    //             returnHeaders: false;
    //             returnStatus: true;
    //         },
    //     ): Promise<{ status: number; response: Awaited<R> }>;
    //     (
    //         context: InputContext_<Path, Options> & {
    //             returnHeaders: false;
    //             returnStatus: false;
    //         },
    //     ): Promise<R>;

    //     // individual flag cases
    //     (
    //         context: InputContext_<Path, Options> & { returnHeaders: true },
    //     ): Promise<{ headers: Headers; response: Awaited<R> }>;
    //     (
    //         context: InputContext_<Path, Options> & { returnStatus: true },
    //     ): Promise<{ status: number; response: Awaited<R> }>;

    //     // default case
    //     (context?: InputContext_<Path, Options>): Promise<R>;

    //     options: Options;
    //     path: Path;
    // }
        > = Endpoint<
            Path,
            HTTPMethod, // Options["method"], // !
            Options["body"] | undefined,      // !
            Options["query"],
            Options["use"] extends undefined ? [] : NonNullable<Options["use"]>,
            R,
            Options["metadata"] extends undefined ? undefined : NonNullable<Options["metadata"]>,
            Options["error"]
        >

    export interface EndpointBaseOptions {
        /**
         * Query Schema
         */
        query?: StandardSchemaV1;
        /**
