### Auth config (if applicable)

```typescript
// auth.ts (sanitized)
import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { nextCookies } from "better-auth/next-js";
import { admin, customSession } from "better-auth/plugins";

export const auth = betterAuth({
  database: drizzleAdapter(db, {
    provider: "mysql",
    schema: {
      user: schema.user,
      session: schema.session,
      account: schema.account,
      verification: schema.verification,
    },
  }),
  emailAndPassword: {
    enabled: true,
    requireEmailVerification: false,
    autoSignIn: false,
    minPasswordLength: 6,
  },
  user: {
    deleteUser: {
      enabled: true,
    },
    additionalFields: {
      role: {
        type: "string",
        defaultValue: "sales-agent",
        required: true,
      },
    },
  },
  session: {
    expiresIn: 60 * 60 * 24 * 7, // 7 days
    updateAge: 60 * 60 * 24,
    freshAge: 60 * 60,
  },
  secret: process.env.BETTER_AUTH_SECRET!,
  baseURL: process.env.NEXT_PUBLIC_BETTER_AUTH_URL || "http://localhost:3000/api/v1/auth",
  trustedOrigins: [
    process.env.NEXT_PUBLIC_BETTER_AUTH_URL || "http://localhost:3000/api/v1/auth",
  ],
  plugins: [
    nextCookies(),
    admin({
      adminRoles: ["admin", "manager"],
      defaultRole: "sales-agent",
    }),
    customSession(async ({ user, session }) => {
      if (!user || !session) {
        return {};
      }

      const dbPermissions = await db.query.permissions.findMany({
        where: eq(schema.permissions.role, user.role),
      });

      return {
        session,
        user,
        userPermissions: dbPermissions,
      };
    }),
  ],
  advanced: {
    database: {
      generateId: false,
    },
    cookiePrefix: "custom-prefix",
    crossSubDomainCookies: {
      enabled: false,
    },
  },
});


import { createAuthClient } from "better-auth/react";
import { adminClient, customSessionClient } from "better-auth/client/plugins";
import { auth, CustomSession } from "./auth";

export const authClient = createAuthClient({
  baseURL:
    process.env.NEXT_PUBLIC_BETTER_AUTH_URL ||
    "http://localhost:3000/api/v1/auth",
  fetchOptions: {
    credentials: "include", // Important for cookies
  },
  plugins: [adminClient(), customSessionClient<typeof auth>()],
});

export const { signIn, signUp, getSession, signOut } = authClient;

export const useSession = () =>
  authClient.useSession() as { data: CustomSession };
